JS = r'''
(()=>{
const data=JSON.parse(document.getElementById('economy-data').textContent),el=id=>document.getElementById(id),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),eur=c=>new Intl.NumberFormat('de-DE',{style:'currency',currency:'EUR',maximumFractionDigits:2}).format(c/100);
const cents=id=>Math.round(Math.max(0,Math.min(Number(el(id).max)||100000,+el(id).value||0))*100);
function annualTax(taxable){let previous=0,total=0;for(const [upper,rate]of data.policy.annual_income_tax_bands){const end=upper===null?taxable:Math.min(taxable,upper);total+=Math.max(0,end-previous)*rate;if(upper===null||taxable<=upper)break;previous=upper;}return Math.round(total);}
function budget(){const a=cents('econ-gross-a'),b=cents('econ-gross-b'),social=Math.round(a*.2)+Math.round(b*.2),rentalIncome=cents('econ-rent-income'),rentalCost=cents('econ-rental-cost'),tax=Math.round((annualTax((a-Math.round(a*.2)+Math.max(0,rentalIncome-rentalCost))*12)+annualTax((b-Math.round(b*.2))*12))/12),income=a+b-social-tax+cents('econ-transfers')+rentalIncome;
const costs=['econ-rent','econ-utilities','econ-food','econ-fixed','econ-leisure','econ-subscriptions','econ-debt'].reduce((s,id)=>s+cents(id),rentalCost),margin=income-costs,free=margin-cents('econ-reserve'),early=cents('econ-cash')-cents('econ-rent')-cents('econ-utilities');
const entries=[['Gesicherte Eingänge netto',income,'Abgaben + Vermietungsüberschusssteuer berücksichtigt'],['Bekannte Cash-Ausgaben',costs,'Konsum und fällige Kreditrate; Rücklage separat'],['Monats-Cashflow',margin,'Bevor weitere Rücklage reserviert wird'],['Nach geplanter Rücklage',free,'Freier zusätzlicher Spielraum; kein neues Guthaben'],['Steuern + Arbeitnehmeranteil',tax+social,'Nicht nochmals als Netto-Ausgabe zählen'],['Früher Zwischenstand',early,'Beispiel: Wohnen/Energie vor dem nächsten Lohn']];
el('econ-budget-results').innerHTML=entries.map(([name,value,detail])=>`<div class="econ-metric ${value<0?'alert':''}"><small>${name}</small><b>${eur(value)}</b><small>${detail}</small></div>`).join('');
el('econ-budget-thought').textContent=free<0?'Eigene begründete Sorge: Die bekannten Kosten passen noch nicht zu den gesicherten Mitteln. Ich möchte zuerst Hilfe, Arbeit und tragbare freie Alternativen prüfen.':early<0?'Der Monat könnte insgesamt passen, aber vor dem nächsten Lohn fehlt kurzfristig Deckung. Ich kläre Termine und einen freiwilligen Übergangsplan.':'Die bekannten Grundkosten sind in diesem Beispiel gedeckt. Ich kann mit ruhigerem Blick planen; private Interessen und eigene Vorlieben bleiben verschieden.';
window.vivariumEconomyDemo={income,costs,margin,free,early,tax,social};}
const defaults={family:[3000,1800,500,0,0,950,280,650,245,220,60,150,200,1600],single:[1200,0,300,0,0,650,180,230,49,20,0,0,50,550],crisis:[0,0,900,0,0,950,280,320,120,0,0,150,0,650],owner:[4200,0,0,950,250,0,330,400,300,240,55,850,350,5000]};
const fields=['gross-a','gross-b','transfers','rent-income','rental-cost','rent','utilities','food','fixed','leisure','subscriptions','debt','reserve','cash'];el('econ-preset').onchange=()=>{defaults[el('econ-preset').value].forEach((v,i)=>el('econ-'+fields[i]).value=v);budget();};for(const id of fields)el('econ-'+id).oninput=budget;
let page=0,filtered=[];for(const domain of [...new Set(data.cases.map(r=>r.domain))])el('econ-case-domain').insertAdjacentHTML('beforeend',`<option>${esc(domain)}</option>`);
function cases(){const query=el('econ-case-search').value.trim().toLocaleLowerCase('de'),domain=el('econ-case-domain').value,size=+el('econ-case-size').value;filtered=data.cases.filter(r=>(domain==='all'||r.domain===domain)&&(!query||JSON.stringify(r).toLocaleLowerCase('de').includes(query)));page=Math.min(Math.max(0,page),Math.max(0,Math.ceil(filtered.length/size)-1));const start=page*size;el('econ-case-count').textContent=filtered.length?`${start+1}–${Math.min(start+size,filtered.length)} / ${filtered.length} Fälle`:'Keine passenden Fälle';el('econ-case-prev').disabled=page===0;el('econ-case-next').disabled=start+size>=filtered.length;
el('econ-case-rows').innerHTML=filtered.slice(start,start+size).map(r=>`<tr><td><b>${esc(r.id+' · '+r.title)}</b><small>${esc(r.domain)}</small></td><td><b>Auslöser:</b> ${esc(r.trigger)}<p>${esc(r.description)}</p></td><td>${esc(r.resolution)}<p><b>Folgen:</b> ${esc(r.effects)}</p></td><td>${esc(r.expectations)}<details><summary>Gegenweg und Buchung</summary><p>${esc(r.constructive_alternative)}</p><p>${esc(r.commit)}</p></details></td></tr>`).join('');}
for(const id of ['econ-case-domain','econ-case-size'])el(id).onchange=()=>{page=0;cases();};let timer;el('econ-case-search').oninput=()=>{clearTimeout(timer);timer=setTimeout(()=>{page=0;cases();},150);};el('econ-case-prev').onclick=()=>{page--;cases();};el('econ-case-next').onclick=()=>{page++;cases();};el('econ-export').onclick=()=>{const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='vivarium-economy-design.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};budget();cases();
})();
'''
